import React, { useState, useEffect } from 'react';
import './AppMain.css'
import { User, Download, Calendar } from 'lucide-react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios'

function AppMain() {
  const location = useLocation();
  const navigate = useNavigate();
  const username = location.state?.username || "Invitado";
  const [showMenu, setShowMenu] = useState(false);
  const [historial, setHistorial] = useState([]);

  // Cargar los datos al cargar la página
  useEffect(() => {
    axios.get('http://localhost:8081/api/history', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    })
      .then(res => {
        setHistorial(res.data);
      })
      .catch(err => {
        console.error("Error al obtener historial:", err);
      });
  }, []);

  const toggleMenu = () => {
    setShowMenu(!showMenu);
  };

  const logout = () => {
    navigate("/");
  };

  return (
    <div className='Main'>
      <header className='Main-header'>
        <img src="/logoQuiros.png" />
        <div className='usuario' onClick={toggleMenu}>
          <User />
          <strong>{username}</strong></div>
        {showMenu && (
          <div className='dropdown'>
            <button onClick={logout}>Cerrar Sesion</button>
          </div>
        )}
      </header>
      <main>
        <div className='Main-menu'>
          <Calendar /><button>Registro Horas</button>
        </div>
        <div className='Main-body'>
          <button>Añadir registro</button>
          <button><Download></Download></button>
          <table className='table'>
            <thead>
              <tr>
                <td>Usuario</td>
                <td>Proyecto</td>
                <td>Tarea</td>
                <td>Horas</td>
                <td>Descripcion</td>
              </tr>
            </thead>
            <tbody>
              {historial.map((item, index) => (
                <tr key={index}>
                  <td>{item.user}</td>
                  <td>{item.proyect}</td>
                  <td>{item.task}</td>
                  <td>{item.hours}</td>
                  <td>{item.description}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}

export default AppMain;
